#include "powder/gpu.hpp"
#include <iostream>
#include <cmath>
using namespace powder;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
int main(){try{MaterialContact m;m.law=ContactLaw::Linear;m.linear={10,0,2.5,0,.4};std::vector<Particle> p;for(unsigned i=0;i<33;++i){Particle a;a.id=i+1;a.diameter_m=.002;a.material.density_kg_m3=1500;a.position_m={i*.0021-.034,0,0};a.velocity_m_s={i%2?.2:-.2,.1,0};p.push_back(a);}GpuSpheres cached,reference;cached.reset(p);reference.reset(p);cached.enable_contacts(m);reference.enable_contacts(m);reference.set_spatial_reuse(false);for(unsigned window=0;window<30;++window){cached.advance_contacts(1e-6,50,{});reference.advance_contacts(1e-6,50,{});auto a=cached.snapshot(),b=reference.snapshot();for(std::size_t i=0;i<a.size();++i)check(a[i].position_m.x==b[i].position_m.x&&a[i].velocity_m_s.x==b[i].velocity_m_s.x,"cached/hash differs from forced sort/binary search");check(cached.contact_pairs()==reference.contact_pairs(),"contact set differs");}
 // An error after 1 or 2 successful steps must expose the accepted buffer, not scratch.
 for(unsigned accepted:{1u,2u}){Particle a;a.id=1;a.diameter_m=.002;a.material.density_kg_m3=1500;a.position_m={1048576.*.002-(accepted+.5)*1e-7,0,0};a.velocity_m_s={1,0,0};GpuSpheres g;g.reset({a});g.enable_contacts(m);bool rejected=false;try{g.advance_contacts(1e-7,5,{});}catch(const std::runtime_error&){rejected=true;}check(rejected&&std::abs(g.physical_time_s()-accepted*1e-7)<1e-20,"accepted prefix clock");auto state=g.snapshot();double expected=a.position_m.x;for(unsigned i=0;i<accepted;++i)expected+=1e-7;check(state[0].position_m.x==expected,"failed batch exposed scratch buffer");g.advance_contacts(1e-9,1,{});check(std::abs(g.physical_time_s()-(accepted*1e-7+1e-9))<1e-20,"failed batch could not recover spatial cache");}
 std::cout<<"PASS exact cached/forced spatial parity, crossing cells, odd/even accepted-prefix rollback and retry\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
